```c
s32 func_80089250(u8 *p1, u8 *p2, u32 n) {
    u8 *d = p1; u8 *s = p2;
    u32 m; s32 c;
    if (n == 0) return 0;
    if (((d - s) & 3) != 0) {
        while (n--) { c = *d - *s; s++; d++; if (c != 0) return c; }
        return 0;
    }
    if ((u32)d & 1) {
        c = *d - *s; s++; d++; if (c != 0) return c; n--;
    }
    m = n;
    if (n >= 2) {
        if ((u32)d & 2) {
            c = *(u16 *)d - *(u16 *)s; s += 2; d += 2;
            if (c != 0) return c;
            n -= 2; m = n;
        }
    }
    n = m >> 2;
    while (n--) { c = *(u32 *)d - *(u32 *)s; s += 4; d += 4; if (c != 0) return c; }
    if (m & 2) { c = *(u16 *)d - *(u16 *)s; s += 2; d += 2; if (c != 0) return c; }
    if (m & 1) { c = *d - *s; return c != 0 ? c : 0; }
    return 0;
}
```
